<?php

/* @autogenerated */
declare(strict_types=1);

use OpenApi\Generator;
use PHPUnit\Framework\TestCase;

/**
 * Contract tests that verify OIDC endpoints appear in the generated OpenAPI spec.
 *
 * These tests prevent silent regressions where a refactor removes #[OA\...] annotations
 * and the entire OIDC surface disappears from the documentation.
 */
final class ApiDocOidcContractTest extends TestCase
{
    private static array $spec = [];

    #[Override]
    public static function setUpBeforeClass(): void
    {
        // Scan only OIDC controllers + Install.php (SecuritySchemes).
        // Restricting the scan path avoids triggering the nikic/php-parser
        // SplObjectStorage::attach() deprecation on every file in src/.
        $scanPaths = [
            __DIR__ . '/../../../src/Features/Oidc/',
            __DIR__ . '/../../../src/Bootstrap/Install.php',
        ];

        // Suppress deprecations during parse so PHPUnit does not print
        // verbose stack traces for each file processed by swagger-php.
        $prevReporting = error_reporting(E_ERROR | E_PARSE);
        $prevHandler   = set_error_handler(null);

        try {
            $gen     = new Generator();
            $openapi = $gen->generate($scanPaths);
            self::$spec = json_decode($openapi->toJson(), true) ?? [];
        } finally {
            error_reporting($prevReporting);
            if ($prevHandler !== null) {
                set_error_handler($prevHandler);
            } else {
                restore_error_handler();
            }
        }
    }

    #[PHPUnit\Framework\Attributes\DataProvider('oidcPathsProvider')]
    public function testOidcPathIsPresent(string $path): void
    {
        $this->assertArrayHasKey(
            $path,
            self::$spec['paths'] ?? [],
            "Expected OIDC path '{$path}' not found in OpenAPI spec."
        );
    }

    public static function oidcPathsProvider(): array
    {
        return [
            'token endpoint'       => ['/oauth/openid/{tenant}/token'],
            'userinfo endpoint'    => ['/oauth/openid/{tenant}/userinfo'],
            'jwks endpoint'        => ['/oauth/openid/{tenant}/jwks'],
            'openid-configuration' => ['/oauth/openid/{tenant}/.well-known/openid-configuration'],
            'introspect endpoint'  => ['/oauth/openid/{tenant}/introspect'],
            'revoke endpoint'      => ['/oauth/openid/{tenant}/revoke'],
            'logout endpoint'      => ['/oauth/openid/{tenant}/logout'],
            'device authorization' => ['/oauth/openid/{tenant}/device'],
            'authorize endpoint'   => ['/oauth/openid/{tenant}/authorize'],
        ];
    }

    public function testTokenEndpointHasPostOperation(): void
    {
        $path = self::$spec['paths']['/oauth/openid/{tenant}/token'] ?? [];
        $this->assertArrayHasKey('post', $path, 'Token endpoint must expose POST.');
    }

    public function testUserInfoEndpointHasGetOperation(): void
    {
        $path = self::$spec['paths']['/oauth/openid/{tenant}/userinfo'] ?? [];
        $this->assertArrayHasKey('get', $path, 'UserInfo endpoint must expose GET.');
    }

    public function testAuthorizeEndpointHasBothMethods(): void
    {
        $path = self::$spec['paths']['/oauth/openid/{tenant}/authorize'] ?? [];
        $this->assertArrayHasKey('get', $path, 'Authorize endpoint must expose GET.');
        $this->assertArrayHasKey('post', $path, 'Authorize endpoint must expose POST.');
    }

    public function testBearerAuthSecuritySchemeIsDefined(): void
    {
        $schemes = self::$spec['components']['securitySchemes'] ?? [];
        $this->assertArrayHasKey('bearerAuth', $schemes, 'bearerAuth security scheme must be defined.');
        $this->assertSame('http', $schemes['bearerAuth']['type']);
        $this->assertSame('bearer', $schemes['bearerAuth']['scheme']);
        $this->assertSame('JWT', $schemes['bearerAuth']['bearerFormat']);
    }

    public function testBasicAuthSecuritySchemeIsDefined(): void
    {
        $schemes = self::$spec['components']['securitySchemes'] ?? [];
        $this->assertArrayHasKey('basicAuth', $schemes, 'basicAuth security scheme must be defined.');
        $this->assertSame('http', $schemes['basicAuth']['type']);
        $this->assertSame('basic', $schemes['basicAuth']['scheme']);
    }

    public function testUserInfoRequiresBearerAuth(): void
    {
        $operation = self::$spec['paths']['/oauth/openid/{tenant}/userinfo']['get'] ?? [];
        $security  = $operation['security'] ?? [];
        $schemes   = $security !== [] ? array_merge(...array_map('array_keys', $security)) : [];
        $this->assertContains('bearerAuth', $schemes, 'userinfo GET must require bearerAuth.');
    }

    public function testIntrospectRequiresBasicAuth(): void
    {
        $operation = self::$spec['paths']['/oauth/openid/{tenant}/introspect']['post'] ?? [];
        $security  = $operation['security'] ?? [];
        $schemes   = $security !== [] ? array_merge(...array_map('array_keys', $security)) : [];
        $this->assertContains('basicAuth', $schemes, 'introspect POST must require basicAuth.');
    }
}
